    for (; i < t.length; i++) { var c = t[i]; if (q) { if (c === '"') { if (t[i + 1] === '"') { f += '"'; i++; } else q = false; } else f += c; } else if (c === '"') q = true; else if (c === d) { row.push(f); f = ""; } else if (c === "\n") { row.push(f); rows.push(row); row = []; f = ""; } else if (c !== "\r") f += c; }
    if (f || row.length) { row.push(f); rows.push(row); } var hd = (rows.shift() || []).map(function (x) { return x.trim(); });
    return rows.filter(function (r2) { return r2.some(function (x) { return x.trim(); }); }).map(function (r2) { var o = {}; hd.forEach(function (h2, j) { o[h2] = (r2[j] || "").trim(); }); return o; });
